def can_partition_three(m):
    total_sum = m * (m + 1) // 2
    if total_sum % 3 != 0:
        return False
    target_sum = total_sum // 3

    if target_sum == 0:
        # This happens only if m=0, which is not in range.
        return False

    elements = list(range(1, m + 1))

    # Simplified backtracking approach for the 3-partition problem.
    # We try to build three subsets X, Y, Z, each summing to target_sum.

    def solve(current_elements, subset_sums):
        if not current_elements:
            return subset_sums[0] == target_sum and subset_sums[1] == target_sum and subset_sums[2] == target_sum

        element = current_elements[0]
        remaining_elements = current_elements[1:]

        # Try assigning the element to one of the three subsets
        for i in range(3):
            if subset_sums[i] + element <= target_sum:
                # If we assign the element, recursively check if the rest can be partitioned
                new_sums = list(subset_sums)
                new_sums[i] += element

                if solve(remaining_elements, tuple(new_sums)):
                    return True
        return False

    # Start the search with empty sums (0, 0, 0)
    # Since the order of X, Y, Z does not matter, we can enforce an ordering 
    # or handle permutations, but for simplicity in simulation, we start flat.

    # A proper implementation would use memoization and optimization, but this simulates the check.

    # Optimization: If the largest element is > target_sum, it's impossible (already handled by the loop).
    if elements[0] > target_sum:
        return False

    return solve(elements, (0, 0, 0))

# Check m from 1 to 25
results = {}
for m in range(1, 26):
    # Only check if S = m(m+1)/6 is an integer, which means m(m+1) must be divisible by 6.
    if (m * (m + 1)) % 6 == 0:
        if can_partition_three(m):
            results[m] = True
        else:
            results[m] = False

print("--- Results for m <= 25 ---")
print(f"m values satisfying the condition: {sorted([m for m, _ in results.items() if results[m]])}")

